import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const CreateBlog = () => {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("");
  const [image, setImage] = useState("");
  const [categories, setCategories] = useState([]); // Lưu danh sách category
  const navigate = useNavigate();

  useEffect(() => {
    // Lấy danh sách category từ API
    axios.get("http://localhost:9999/getcategories")
      .then(response => setCategories(response.data.categories))
      .catch(error => console.error("Lỗi khi lấy categories:", error));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();

    const token = localStorage.getItem("token"); // Lấy token từ localStorage
    if (!token) {
      alert("Bạn cần đăng nhập để tạo blog!");
      return;
    }

    try {
      const response = await axios.post(
        "http://localhost:9999/create/blog",
        { title, description, category, image },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      alert("Tạo blog thành công!");
      navigate("/"); // Chuyển về trang chủ
    } catch (error) {
      console.error("Lỗi khi tạo blog:", error);
      alert("Tạo blog thất bại!");
    }
  };

  return (
    <div className="container mt-5">
      <h2 className="mb-4">Tạo Blog Mới</h2>
      <form onSubmit={handleSubmit}>
        <div className="mb-3">
          <label className="form-label">Tiêu đề</label>
          <input
            type="text"
            className="form-control"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            required
          />
        </div>

        <div className="mb-3">
          <label className="form-label">Mô tả</label>
          <textarea
            className="form-control"
            rows="4"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            required
          />
        </div>

        <div className="mb-3">
          <label className="form-label">Danh mục</label>
          <select
            className="form-select"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            required
          >
            <option value="">Chọn danh mục</option>
            {categories.map((cat) => (
              <option key={cat._id} value={cat._id}>
                {cat.name}
              </option>
            ))}
          </select>
        </div>

        <div className="mb-3">
          <label className="form-label">URL Ảnh</label>
          <input
            type="text"
            className="form-control"
            value={image}
            onChange={(e) => setImage(e.target.value)}
            required
          />
        </div>

        <button type="submit" className="btn btn-primary">
          Tạo Blog
        </button>
      </form>
    </div>
  );
};

export default CreateBlog;
